{
  "story": "Plants capture sunlight in chloroplasts to convert carbon dioxide and water into chemical energy and oxygen.",
  "aha": {
    "stateId": "light",
    "observation": "Light energy splits water molecules to release oxygen and power ATP formation."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "reason": "variant.states.why"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Photosynthesis Stage",
      "options": [
        "Absorption",
        "Light Reaction",
        "Calvin Cycle"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Photosynthesis Overview",
        "regions": [
          {
            "id": "chloroplast",
            "label": "Chloroplast",
            "kind": "organelle",
            "values": ["Thylakoid", "Stroma"]
          },
          {
            "id": "inputs",
            "label": "Inputs",
            "kind": "material",
            "values": ["Light", "H2O", "CO2"]
          }
        ],
        "states": [
          {
            "id": "absorb",
            "label": "Absorption",
            "short": "Light capture",
            "sentence": "Chlorophyll pigments absorb sunlight inside the thylakoid membrane.",
            "why": "Initiates energy capture.",
            "active": ["inputs"],
            "calloutRegion": "chloroplast",
            "readouts": [
              {
                "id": "r1",
                "label": "Photon Energy",
                "value": "High"
              }
            ]
          },
          {
            "id": "light",
            "label": "Light Reaction",
            "short": "Water splitting",
            "sentence": "Water splits into oxygen, electrons, and protons using solar energy.",
            "why": "Generates ATP and NADPH.",
            "active": ["chloroplast"],
            "calloutRegion": "chloroplast",
            "readouts": [
              {
                "id": "r2",
                "label": "Oxygen Released",
                "value": "Yes"
              }
            ]
          },
          {
            "id": "calvin",
            "label": "Calvin Cycle",
            "short": "Sugar building",
            "sentence": "Carbon dioxide is fixed in the stroma to synthesize glucose.",
            "why": "Stores energy long term.",
            "active": ["chloroplast"],
            "calloutRegion": "chloroplast",
            "readouts": [
              {
                "id": "r3",
                "label": "Glucose Yield",
                "value": "1 Molecule"
              }
            ]
          }
        ]
      }
    ]
  }
}
